                # Increment the number of separated chatting pairs for the current aisle position
                separated_pairs[(i, j)] = separated_pairs.get((i, j), 0) + 1

    # Find the aisle position with the maximum number of separated chatting pairs
    max_separated_pairs = max(separated_pairs.values())
    max_aisle_positions = [k for k, v in separated_pairs.items() if v == max_separated_pairs]

    # Return the row and column indices of the optimal aisle positions
    return (str(max_aisle_positions[0]), ' '.join(str(p) for p in max_aisle_positions[1:]))

