def is_valid_aisle(i, j, M, N, K, L):
    # Check if the position is within the bounds of the classroom
    if i < 0 or i >= M or j < 0 or j >= N:
        return False
    # Check if the position is already occupied by another aisle
    for (i1, j1) in aisle_positions:
        if i1 == i and j1 == j:
            return False
    # Check if the position is too close to the edge of the classroom
    if i == 0 or i == M - 1 or j == 0 or j == N - 1:
        return False
    # Check if the position is too close to another aisle
    for (i1, j1) in aisle_positions:
        if abs(i1 - i) <= K and abs(j1 - j) <= L:
