def count_passing_ways(n: int, m: int) -> int:
    # Initialize a two-dimensional array to store the results
    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the first row of the array with the number of ways to pass the ball to each student
    for i in range(n):
        dp[i][0] = 1

    # Iterate over the rows of the array
    for i in range(1, m + 1):
        # Iterate over the columns of the array
        for j in range(n):
            # If the current student is the starting student, the number of ways to pass the ball is 1
