def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Populate the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # Case 1: Include the current item in the box
            if i - volumes[j - 1] >= 0:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1] + volumes[j - 1], dp[i][j - 1])
            # Case 2: Exclude the current item from the box
            else:
                dp[i][j] = dp[i][j - 1]

    # Return the minimum remaining space in the box
    return V - dp[-1][-1]

