    for i, budget in enumerate(budgets, 1):
        # If the budget is less than or equal to 100, there is nothing to save
        if budget <= 100:
            continue
        # Calculate the amount saved and add it to the total saved
        amount_saved = min(budget - 100, 2 * (i % 2))
        total_saved += amount_saved

